function formValue(){const generationEditor=generationEditorSnapshot({version:1,promptChoice:$('#prompt-choice').value,refinementModel:$('#refinement-model').value,refinedPrompt:$('#refined-prompt').value,refinedNegative:$('#refined-negative').value,builder:mode.endsWith('video')&&typeof promptBuilder!=='undefined'?promptBuilder.snapshot():null});const value={mode,model:$('#model').value,uploadId,enhance:false,generationEditor};if(mode.endsWith('video')&&typeof promptBuilder!=='undefined'&&promptBuilder?.voiceAudioId())value.voiceAudioId=promptBuilder.voiceAudioId();for(const k of ['prompt','negative','aspect','quality','resolution'])value[k]=$('#'+k).value;for(const k of ['duration','seed','guidance'])value[k]=+$('#'+k).value;return value;}
