async function waitRefinement(id,source){for(let i=0;i<600;i++){const list=await api('/api/jobs'),j=(Array.isArray(list)?list:list.jobs||[]).find(x=>x.id===id);if(!j)throw Error('보정 작업을 찾을 수 없습니다.');if(j.state==='complete'){if(sourceKey()!==source)throw Error('입력이 바뀌었습니다. 보정 프롬프트를 다시 생성해 주세요.');promptCandidate={...j,source};$('#refined-prompt').value=j.prompt;$('#refined-negative').value=j.negative;$('#prompt-choice').value='refined';$('#refine-result').hidden=false;$('#prompt-options').open=true;$('#refine-status').textContent='보정문을 확인하고 원문 또는 보정문을 선택한 뒤 만들기를 누르세요.';return;}if(['blocked','cancelled'].includes(j.state)){sessionStorage.removeItem('creator-refinement');throw Error(j.message||'보정을 다시 시도해 주세요.');}$('#refine-status').textContent=j.message||'영어 보정문 생성 중…';await new Promise(r=>setTimeout(r,2000));}throw Error('보정 대기가 길어지고 있습니다. 진행 화면에서 작업을 확인하세요.');}
