async function prepareControl(action,jobId){try{controlPlan=await api('/api/control/prepare',{method:'POST',body:JSON.stringify({action,jobId})});$('#control-title').textContent=controlPlan.title;$('#control-description').textContent=controlPlan.description;$('#control-dialog').showModal();}catch(e){toast(e.message);}}
$('#reset-web').onclick=()=>prepareControl('web-reset');$('#stop-job').onclick=()=>prepareControl('stop');$('#reset-server').onclick=()=>prepareControl('reset');$('#control-cancel').onclick=()=>{controlPlan=null;$('#control-dialog').close();};$('#control-dialog').addEventListener('cancel',()=>controlPlan=null);
$('#control-confirm').onclick=async()=>{if(!controlPlan)return;const plan=controlPlan;controlPlan=null;$('#control-dialog').close();try{const result=await api('/api/control/execute',{method:'POST',body:JSON.stringify({token:plan.token})});toast(result.message);if(plan.action==='web-reset'){$('#web-note').textContent='재시작 요청 완료 · 재연결 확인 중';}await refresh();}catch(e){toast(e.message);}};

$('#favorites-toggle').onclick=()=>{setOrderMode(false);selectionMode=false;favorites=!favorites;trash=false;$('#trash-toggle').textContent='휴지통';$('#favorites-toggle').setAttribute('aria-pressed',String(favorites));selection.clear();lastGallery='';render();};
const shareCache=new Map();
function shareResult(j,button){const prepared=shareCache.get(j.id);if(prepared){if(navigator.canShare?.({files:prepared}))navigator.share({files:prepared}).catch(e=>{if(e.name!=='AbortError')toast('저장창을 열지 못했습니다.');});else for(const a of j.assets||[]){const link=el('a');link.href=a.url+'?download=1';link.download=a.filename;document.body.append(link);link.click();link.remove();}return;}button.disabled=true;setIcon(button,'loader','파일 준비 중');Promise.all((j.assets||[]).map(async a=>{if((j.assets||[]).reduce((n,x)=>n+x.bytes,0)>209715200)throw Error('200MB 이상 파일은 전체화면 또는 다운로드로 저장하세요.');const r=await fetch(a.url);if(!r.ok)throw Error('공유 파일 준비 실패');const blob=await r.blob();return new File([blob],a.filename,{type:blob.type});})).then(next=>{if(shareCache.size>=3)shareCache.delete(shareCache.keys().next().value);shareCache.set(j.id,next);button.disabled=false;setIcon(button,'save','저장 열기');toast('파일이 준비됐어요. 저장 열기를 누른 뒤 사진·비디오 저장을 선택하세요.');}).catch(e=>{button.disabled=false;setIcon(button,'save','결과 파일 저장');toast(e.message);});}

$('#close-selection').onclick=()=>{selectionMode=false;selection.clear();updateSelection();};
function openPrompt(j){if(j.contentProjectId){selectedTool(j.mode);void(j.mode==='video-edit'?openMediaEditor(j.mode,j.contentProjectId):openContentTool(j.mode,j.contentProjectId));return;}const content=$('#prompt-content');content.replaceChildren();for(const [title,text]of [['프롬프트',j.originalPrompt||j.prompt||j.result],['LLM 수정 프롬프트',j.refinedAt?j.prompt:(j.enhance?'아직 보정문이 생성되지 않았습니다.':null)],['네거티브 프롬프트',j.negative],['영상 길이',j.mode?.endsWith('video')?videoLength(j):null],['생성 설정',`${names[j.mode]||j.mode} · ${j.model||'모델 기본값'}\n시드 ${j.seed??'기록 없음'} · 설명 충실도 ${j.guidance??'기록 없음'}\n${j.aspect||'9:16'}${j.resolution?' · '+outputSize(j.aspect||'9:16',j.resolution).join(' × '):''} · ${timing(j)}`]]){if(text){content.append(el('h2',null,title),el('p',null,text));}}if(j.uploadId&&!j.deletedAt){const thumb=el('button','prompt-source-image'),image=el('img');image.src='/api/job-inputs/'+encodeURIComponent(j.uploadId);image.alt='원본 사진 전체 보기';thumb.type='button';thumb.setAttribute('aria-label','원본 사진 전체 보기');thumb.append(image);thumb.onclick=()=>{const full=$('#original-image');full.src='/api/job-inputs/'+encodeURIComponent(j.uploadId)+'?original=1';$('#original-image-dialog').showModal();};content.prepend(el('h2',null,'원본 사진'),thumb);}const again=$('#prompt-recreate');again.textContent=j.mode==='card-news'?'카드뉴스 원본 편집':'동일조건 생성하기';again.hidden=!!j.deletedAt;again.onclick=()=>{if(j.mode==='card-news'){$('#prompt-dialog').close();void openCardNews(j.cardProjectId);}else regenerate(j);};$('#prompt-dialog').showModal();}
$('#close-prompt').onclick=()=>$('#prompt-dialog').close();
$('#close-original-image').onclick=()=>$('#original-image-dialog').close();$('#original-image-dialog').addEventListener('close',()=>$('#original-image').removeAttribute('src'));

async function deleteResult(j){try{await api('/api/gallery/delete',{method:'POST',body:JSON.stringify({ids:[j.id]})});shareCache.delete(j.id);jobs=await api('/api/jobs');lastGallery='';render();toast('휴지통으로 이동했어요. 복원할 수 있습니다.');}catch(e){toast(e.message);}}
async function favoriteResult(j){if(j.favorite)return toast('이미 즐겨찾기에 있어요.');try{await api('/api/gallery/favorite',{method:'POST',body:JSON.stringify({id:j.id,favorite:true})});jobs=await api('/api/jobs');lastGallery='';render();toast('즐겨찾기에 추가했어요.');}catch(e){toast(e.message);}}
const viewerFiles=new Map();let viewerSaveVersion=0;
function viewerDownload(a){const link=el('a');link.href=a.url+'?download=1';link.download=a.filename;document.body.append(link);link.click();link.remove();}
async function prepareViewerSave(x){const version=++viewerSaveVersion,button=$('#viewer-save');button.disabled=true;button.textContent='준비 중';button.onclick=null;try{let file=viewerFiles.get(x.a.filename);const canPrepare=typeof navigator.share==='function'&&typeof navigator.canShare==='function'&&!(x.a.bytes>209715200);if(canPrepare&&!file){const r=await fetch(x.a.url);if(!r.ok)throw Error('저장 파일을 준비하지 못했습니다.');const blob=await r.blob();file=new File([blob],x.a.filename,{type:blob.type});if(viewerFiles.size>=3)viewerFiles.delete(viewerFiles.keys().next().value);viewerFiles.set(x.a.filename,file);}if(version!==viewerSaveVersion)return;button.disabled=false;button.textContent='저장';button.onclick=()=>{if(file&&navigator.canShare?.({files:[file]}))navigator.share({files:[file]}).catch(e=>{if(e.name!=='AbortError')toast('저장창을 열지 못했습니다.');});else viewerDownload(x.a);};}catch(e){if(version!==viewerSaveVersion)return;button.disabled=false;button.textContent='저장';button.onclick=()=>viewerDownload(x.a);toast(e.message+' 저장 버튼으로 직접 다운로드할 수 있습니다.');}}

const repeatKeys=new Map();
async function editImageVideo(j,button){if(button.disabled)return;button.disabled=true;try{const draft=await api('/api/gallery/video-draft',{method:'POST',body:JSON.stringify({id:j.id})});sessionStorage.removeItem('creator-refinement');regenerate({...draft,state:'draft',prompt:'',originalPrompt:'',negative:'',originalNegative:'',refinedAt:null,enhance:false,generationEditor:null,refinementModel:null});$('#prompt-options').open=false;const image=j.assets.find(a=>a.kind==='image');if(image){$('#photo-preview').src=image.url;$('#photo-preview').hidden=false;$('#upload-label').hidden=true;}}catch(e){toast(e.message);}finally{button.disabled=false;}}
async function repeatJob(j,button,imageToVideo=false){if(button.disabled)return;const token=j.id+':'+imageToVideo;let requestId=repeatKeys.get(token);if(!requestId){requestId=crypto.randomUUID();repeatKeys.set(token,requestId);}button.disabled=true;try{await api('/api/jobs',{method:'POST',headers:{'Idempotency-Key':requestId},body:JSON.stringify({recreateId:j.id,imageToVideo,randomizeSeed:!imageToVideo})});repeatKeys.delete(token);$('#prompt-dialog').close();view('queue');await refresh();toast(imageToVideo?'같은 프롬프트와 화면 설정으로 영상 제작을 접수했어요.':'시드를 랜덤으로 바꿔 다시 제작합니다.');}catch(e){toast(e.message);}finally{button.disabled=false;}}
function moveViewer(delta){const next=viewerIndex+delta;if(next<0||next>=mediaList().length)return;viewerIndex=next;showMedia();const content=$('#result-content');content.animate?.([{opacity:.25,transform:`translateX(${delta*35}px)`},{opacity:1,transform:'translateX(0)'}],{duration:180,easing:'ease-out'});}
$('#viewer-prev').onclick=()=>moveViewer(-1);$('#viewer-next').onclick=()=>moveViewer(1);
let viewerTouch=null,viewerSuppressUntil=0;
$('#result-content').addEventListener('touchstart',e=>{if(e.touches.length!==1){viewerTouch=null;return;}const t=e.touches[0];if(e.target.closest?.('.video-controls')||e.target.closest?.('.image-viewport')?.dataset.zoomed==='true'){viewerTouch=null;return;}if(e.target.tagName==='VIDEO'&&e.target.controls&&t.clientY>e.target.getBoundingClientRect().bottom-65){viewerTouch=null;return;}viewerTouch={x:t.clientX,y:t.clientY};},{passive:true,capture:true});
$('#result-content').addEventListener('touchend',e=>{if(!viewerTouch)return;const t=e.changedTouches[0],dx=t.clientX-viewerTouch.x,dy=t.clientY-viewerTouch.y;viewerTouch=null;const horizontal=Math.abs(dx)>65&&Math.abs(dx)>Math.abs(dy)*1.8,vertical=Math.abs(dy)>48&&Math.abs(dy)>Math.abs(dx)*1.25;if(horizontal||vertical){if(e.cancelable)e.preventDefault();viewerSuppressUntil=Date.now()+600;moveViewer(horizontal?(dx<0?1:-1):(dy<0?-1:1));}},{passive:false,capture:true});
$('#result-content').addEventListener('touchcancel',()=>viewerTouch=null);
$('#result-content').addEventListener('touchmove',e=>{if(e.touches.length>1){viewerTouch=null;return;}if(viewerTouch&&Math.max(Math.abs(e.touches[0].clientX-viewerTouch.x),Math.abs(e.touches[0].clientY-viewerTouch.y))>12&&e.cancelable)e.preventDefault();},{passive:false,capture:true});
$('#result-content').addEventListener('click',e=>{if(Date.now()<viewerSuppressUntil){e.preventDefault();e.stopImmediatePropagation();}},true);
$('#result-dialog').addEventListener('keydown',e=>{if(e.key==='ArrowLeft')moveViewer(-1);if(e.key==='ArrowRight')moveViewer(1);if(e.key==='ArrowUp'){e.preventDefault();moveViewer(-1);}if(e.key==='ArrowDown'){e.preventDefault();moveViewer(1);}});
initEdgeRefresh({canRefresh:()=>ready&&!galleryDragging&&!orderMode&&!queueOrdering,onRefresh:async()=>{if(!await refresh(true))throw Error('연결을 확인해 주세요.');if(!$('#connect').hidden){statsUpdated=0;await Promise.all([refreshGenerationStats(),refreshCloudStatus(),assetManager.refresh()]);}if(!$('#cards').hidden)await refreshCardNews();if(!$('#workbench').hidden)await refreshContentTools();}});
const promptBuilder=initPromptBuilder({api,getMode:()=>mode,getContext:()=>({provider:$('#provider').value,model:$('#model').value,duration:$('#duration').value}),getExisting:()=>({positive:$('#prompt').value,negative:$('#negative').value}),canApply:()=>!refineBusy,bindDictation,icon,onNegativeChange:negative=>{$('#negative').value=negative;},onApply:({positive,negative})=>{promptDictation.cancel();$('#prompt').value=positive;$('#negative').value=negative;$('#prompt-choice').value='original';$('#refined-prompt').value='';$('#refined-negative').value='';$('#refine-status').textContent='';promptCandidate=null;sessionStorage.removeItem('creator-refinement');},toast});
initMediaEditor({api,toast,view,selected:selectedTool,bindDictation,icon});initContentTools({api,toast,view,selected:selectedTool});hydrateIcons();initCardNews({api,toast,view});initChat({api,toast});initNotifications({api,toast});
function swipeAction(dx,dy){return Math.abs(dx)>=72&&Math.abs(dx)>Math.abs(dy)*1.8?(dx<0?'favorite':'delete'):null;}
function enableSwipe(card,j){let start=null,suppressUntil=0;card.addEventListener('pointerdown',e=>{if(orderMode||e.pointerType==='mouse'||selectionMode||e.target.closest('input'))return;start={x:e.clientX,y:e.clientY,id:e.pointerId};});card.addEventListener('pointermove',e=>{if(!start||e.pointerId!==start.id)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;if(Math.abs(dy)>Math.abs(dx)&&Math.abs(dy)>18){start=null;card.classList.remove('swiping-left','swiping-right');return;}card.classList.toggle('swiping-left',dx< -30&&Math.abs(dx)>Math.abs(dy)*1.8);card.classList.toggle('swiping-right',dx>30&&Math.abs(dx)>Math.abs(dy)*1.8);});card.addEventListener('pointerup',e=>{card.classList.remove('swiping-left','swiping-right');if(!start||e.pointerId!==start.id)return;const action=swipeAction(e.clientX-start.x,e.clientY-start.y);start=null;if(!action)return;suppressUntil=Date.now()+600;e.preventDefault();action==='delete'?void deleteResult(j):void favoriteResult(j);});card.addEventListener('pointercancel',()=>{start=null;card.classList.remove('swiping-left','swiping-right');});card.addEventListener('click',e=>{if(Date.now()<suppressUntil){e.preventDefault();e.stopImmediatePropagation();}},true);}

